    22  #include <sys/un.h>
    23  #include "h2o.h"
    24  #include "h2o/socketpool.h"
    25
    26  struct rp_handler_t {
    27      h2o_handler_t super;
    28      h2o_url_t upstream;         /* host should be NULL-terminated */
    29      h2o_socketpool_t *sockpool; /* non-NULL if config.use_keepalive == 1 */
    30      h2o_proxy_config_vars_t config;
    31  };
    32
    33  static int on_req(h2o_handler_t *_self, h2o_req_t *req)
    34  {
    35      struct rp_handler_t *self = (void *)_self;
    36      h2o_req_overrides_t *overrides = h2o_mem_alloc_pool(&req->pool, sizeof(*overrides));
    37      const h2o_url_scheme_t *scheme;
    38      h2o_iovec_t *authority;
    39
    40      /* setup overrides */
    41      *overrides = (h2o_req_overrides_t){NULL};
    42      if (self->sockpool != NULL) {
    43          overrides->socketpool = self->sockpool;
    44      } else if (self->config.preserve_host) {
    45          overrides->hostport.host = self->upstream.host;
    46          overrides->hostport.port = h2o_url_get_port(&self->upstream);
    47      }
    48      overrides->location_rewrite.match = &self->upstream;
    49      overrides->location_rewrite.path_prefix = req->pathconf->path;
    50      overrides->use_proxy_protocol = self->config.use_proxy_protocol;
    51      overrides->client_ctx = h2o_context_get_handler_context(req->conn->ctx, &self->super);
    52      overrides->headers_cmds = self->config.headers_cmds;
    53
    54      /* determine the scheme and authority */
    55      if (self->config.preserve_host) {
    56          scheme = req->scheme;
    57          authority = &req->authority;
    58          overrides->proxy_preserve_host = 1;
    59      } else {
    60          scheme = self->upstream.scheme;
    61          authority = &self->upstream.authority;
    62          overrides->proxy_preserve_host = 0;
    63      }
    64
    65      /* request reprocess */
    66      h2o_reprocess_request(req, req->method, scheme, *authority,
    67                            h2o_build_destination(req, self->upstream.path.base, self->upstream.path.len, 0), overrides, 0);
    68
    69      return 0;
    70  }
    71
    72  static void on_context_init(h2o_handler_t *_self, h2o_context_t *ctx)
    73  {
    74      struct rp_handler_t *self = (void *)_self;
    75
    76      /* use the loop of first context for handling socketpool timeouts */
    77      if (self->sockpool != NULL && self->sockpool->timeout == UINT64_MAX)
    78          h2o_socketpool_set_timeout(self->sockpool, ctx->loop, self->config.keepalive_timeout);
    79
    80      /* setup a specific client context only if we need to */
    81      if (ctx->globalconf->proxy.io_timeout == self->config.io_timeout && !self->config.websocket.enabled &&
    82          self->config.ssl_ctx == ctx->globalconf->proxy.ssl_ctx)
    83          return;
    84
    85      h2o_http1client_ctx_t *client_ctx = h2o_mem_alloc(sizeof(*ctx));
    86      client_ctx->loop = ctx->loop;
    87      client_ctx->getaddr_receiver = &ctx->receivers.hostinfo_getaddr;
    88      if (ctx->globalconf->proxy.io_timeout == self->config.io_timeout) {
    89          client_ctx->io_timeout = &ctx->proxy.io_timeout;
    90      } else {
    91          client_ctx->io_timeout = h2o_mem_alloc(sizeof(*client_ctx->io_timeout));
    92          h2o_timeout_init(client_ctx->loop, client_ctx->io_timeout, self->config.io_timeout);
    93      }
    94      if (self->config.websocket.enabled) {
    95          /* FIXME avoid creating h2o_timeout_t for every path-level context in case the timeout values are the same */
    96          client_ctx->websocket_timeout = h2o_mem_alloc(sizeof(*client_ctx->websocket_timeout));
    97          h2o_timeout_init(client_ctx->loop, client_ctx->websocket_timeout, self->config.websocket.timeout);
    98      } else {
    99          client_ctx->websocket_timeout = NULL;
   100      }
   101      client_ctx->ssl_ctx = self->config.ssl_ctx;
   102
   103      h2o_context_set_handler_context(ctx, &self->super, client_ctx);
   104  }
   105
   106  static void on_context_dispose(h2o_handler_t *_self, h2o_context_t *ctx)
   107  {
   108      struct rp_handler_t *self = (void *)_self;
   109      h2o_http1client_ctx_t *client_ctx = h2o_context_get_handler_context(ctx, &self->super);
   110
   111      if (client_ctx == NULL)
   112          return;
   113
   114      if (client_ctx->io_timeout != &ctx->proxy.io_timeout) {
   115          h2o_timeout_dispose(client_ctx->loop, client_ctx->io_timeout);
   116          free(client_ctx->io_timeout);
   117      }
   118      if (client_ctx->websocket_timeout != NULL) {
   119          h2o_timeout_dispose(client_ctx->loop, client_ctx->websocket_timeout);
   120          free(client_ctx->websocket_timeout);
   121      }
   122      free(client_ctx);
   123  }
   124
   125  static void on_handler_dispose(h2o_handler_t *_self)
   126  {
   127      struct rp_handler_t *self = (void *)_self;
   128
   129      if (self->config.ssl_ctx != NULL)
   130          SSL_CTX_free(self->config.ssl_ctx);
   131      free(self->upstream.host.base);
   132      free(self->upstream.path.base);
   133      if (self->sockpool != NULL) {
   134          h2o_socketpool_dispose(self->sockpool);
   135          free(self->sockpool);
   136      }
   137  }
